pull_request.diff:
@@ -0,0 +1,7 @@
+---
+'element-plus': patch
+---
+
+Preserve the existing Button keyboard focus ring when hover and focus-visible
+coexist on a coarse pointer device. Limit hover ring suppression to buttons
+without focus-visible, retaining the existing non-keyboard focus rule.
@@ -0,0 +1,8 @@
+---
+'element-plus': patch
+---
+
+Restore the existing public Button text, hover/focus link-text, and active color
+variables for enabled danger link buttons after the product theme's generic and
+coarse-pointer overrides. Keep disabled styling, keyboard focus rings, and other
+button types unchanged.
@@ -3191,7 +3191,7 @@ button.#{$namespace}-card:active {
     -webkit-tap-highlight-color: transparent;
   }

-  .#{$namespace}-button:not(.is-disabled):hover,
+  .#{$namespace}-button:not(.is-disabled):hover:not(:focus-visible),
   .#{$namespace}-button:not(.is-disabled):focus:not(:focus-visible) {
     transform: none;
     box-shadow: none !important;
@@ -3446,3 +3446,17 @@ button.#{$namespace}-card:active {
     background: rgba(255, 255, 255, 0.12);
   }
 }
+
+// Preserve the public danger-link color variables after coarse-pointer resets.
+.#{$namespace}-button.#{$namespace}-button--danger.is-link:not(.is-disabled) {
+  color: getCssVar('button', 'text-color');
+
+  &:hover,
+  &:focus {
+    color: getCssVar('button', 'hover', 'link-text-color');
+  }
+
+  &:active {
+    color: getCssVar('button', 'active-color');
+  }
+}

